\section{Introduction}

Questions about when a natural arithmetic expression can be a perfect square form a classical strand of number theory. This paper concerns products of the form
\[
P_n(a,b) := \bigl(a^n+1\bigr)\bigl(b^n+1\bigr),
\]
where the two bases are coprime and the exponent is odd.

At first glance the difficulty appears to scale with $n$: as the exponent grows, $a^n+1$ and $b^n+1$ become enormous. The organizing discovery of this work is the opposite. The obstruction to $P_n(a,b)$ being a square does not live in the $n$-th powers; it lives in the small quantities $a+1$ and $b+1$, and the exponent is, for the decisive prime, entirely inert.

Our contributions are: (1) an exponent-invariance identity, $v_2(a^n+1)=v_2(a+1)$ for odd $n$; (2) a uniform parity obstruction; (3) an exhaustive certificate over a bounded window; and (4) a conjectural framework generalizing the mechanism.

\section{Definitions and Notation}

Throughout, all variables denote nonnegative integers unless stated otherwise.

\begin{definition}[$p$-adic valuation]
For a prime $p$ and a positive integer $m$, the \emph{$p$-adic valuation} $\vp_p(m)$ is the largest integer $k$ with $p^k \mid m$. It satisfies $\vp_p(mn)=\vp_p(m)+\vp_p(n)$.
\end{definition}

\begin{definition}[Perfect square]
A natural number $N$ is a \emph{perfect square} if $N=x^2$ for some integer $x$. Equivalently, $N$ is a perfect square if and only if $\vp_p(N)$ is even for every prime $p$.
\end{definition}

\begin{definition}[Shifted-power product]
For positive integers $a,b$ and exponent $n$, set $P_n(a,b)=(a^n+1)(b^n+1)$.
\end{definition}

The characterization of squares by even valuations is the engine of the paper: to disprove squareness it suffices to exhibit a single prime whose valuation in $P_n(a,b)$ is odd.

\section{The Exponent-Invariance Mechanism}

\begin{theorem}[Exponent-invariance of $v_2$]\label{thm:collapse}
For every odd positive integer $n$ and every positive integer $a$,
\[
\vp_2\!\left(a^n+1\right)=\vp_2(a+1).
\]
\end{theorem}

\begin{proof}
For odd $n$ the identity
\[
a^n+1=(a+1)\,Q_n(a),\qquad Q_n(a)=\sum_{k=0}^{n-1}(-1)^k a^{\,n-1-k}=a^{n-1}-a^{n-2}+\cdots-a+1,
\]
holds. It suffices to show $Q_n(a)$ is odd, for then $\vp_2(a^n+1)=\vp_2(a+1)+\vp_2(Q_n(a))=\vp_2(a+1)$. Reduce modulo $2$: if $a$ is even, all terms $a^{n-1-k}$ with $k<n-1$ are even and the final term is $1$, so $Q_n(a)\equiv 1$; if $a$ is odd, each of the $n$ terms is odd and $n$ is odd, so the sum of $n$ odd numbers is odd, giving $Q_n(a)\equiv 1$. In both cases $Q_n(a)$ is odd.
\end{proof}

\begin{remark}
Theorem~\ref{thm:collapse} is the $p=2$ specialization of the lifting-the-exponent principle. For a general prime $p\mid a+1$ and odd $n$, $\vp_p(a^n+1)=\vp_p(a+1)+\vp_p(n)$; when $p\nmid n$ the second term vanishes. Since $2\nmid n$ automatically for odd $n$, the case $p=2$ needs no exponent correction.
\end{remark}

\begin{theorem}[Parity criterion]\label{thm:parity}
Let $a,b$ be positive integers and $n$ an odd positive integer. If $\vp_2(a+1)+\vp_2(b+1)$ is odd, then $P_n(a,b)$ is not a perfect square.
\end{theorem}

\begin{proof}
By additivity of valuation and Theorem~\ref{thm:collapse},
\[
\vp_2\bigl(P_n(a,b)\bigr)=\vp_2(a^n+1)+\vp_2(b^n+1)=\vp_2(a+1)+\vp_2(b+1).
\]
If this is odd, then $P_n(a,b)$ has an odd power of $2$ in its factorization and is not a perfect square.
\end{proof}

Theorem~\ref{thm:parity} disposes of an infinite family of cases at once: the exponent $n$ is eliminated and squareness is refuted from the residues of $a$ and $b$ alone. The criterion is silent precisely when $\vp_2(a+1)+\vp_2(b+1)$ is even; in that regime non-squareness must be enforced by another prime or by an archimedean argument trapping $P_n(a,b)$ strictly between consecutive squares.

\subsection*{Worked examples}
Let $a=5$, $b=6$: then $v_2(a+1)=1$, $v_2(b+1)=0$, sum odd, so $(5^n+1)(6^n+1)$ is never a square for odd $n$; e.g. $5^3+1=126=2\cdot 63$ has $v_2=1=v_2(5+1)$. Let $a=3$, $b=4$: sum $v_2(a+1)+v_2(b+1)=2$ is even and Theorem~\ref{thm:parity} is silent, yet $(3^3+1)(4^3+1)=1820$ satisfies $42^2<1820<43^2$, excluded by size. The coprimality hypothesis is a normalization keeping the two factors arithmetically independent at each prime; it is not needed for Theorem~\ref{thm:parity} but is natural for the odd-prime sieve.

\section{An Exhaustive Certificate on a Bounded Window}

\begin{theorem}[Bounded impossibility]\label{thm:bounded}
For all integers $a,b$ with $1<a<b<100$ and $\gcd(a,b)=1$, and all $n\in\{3,5,7,9\}$, the product $P_n(a,b)=(a^n+1)(b^n+1)$ is not a perfect square.
\end{theorem}

\begin{proof}
The parameter space is finite: $a\in\{2,\dots,98\}$, $b\in\{a+1,\dots,99\}$, and $n\in\{3,5,7,9\}$. Restricting to coprime pairs, one enumerates every admissible triple $(a,b,n)$, forms $P_n(a,b)$, and checks non-squareness via an integer square-root test. Every case passes, so the claim follows by exhaustion.
\end{proof}

The large majority of triples are eliminated instantly by the parity criterion (Theorem~\ref{thm:parity}); the exhaustive check confirms the residual parity-even triples are excluded as well, invariably by archimedean trapping.

\section{Algorithms}

\textbf{Algorithm A (Parity screen).} Given $(a,b)$, compute $\vp_2(a+1)$ and $\vp_2(b+1)$ by repeated division; return ``not a square for all odd $n$'' if their sum is odd. Cost $O(\log a+\log b)$, no $n$-th power formed.

\textbf{Algorithm B (Exhaustive certificate).} Iterate over $2\le a<b<100$ with $\gcd(a,b)=1$ and $n\in\{3,5,7,9\}$; test squareness of $N=(a^n+1)(b^n+1)$ by comparing $\lfloor\sqrt N\rfloor^2$ with $N$. Report any square (there are none).

\section{Conjectural Framework}

\begin{conjecture}[Odd-prime sieve]
Fix an odd prime $p$. For coprime $1<a<b$ and any odd $n$ with $p\nmid n$, if $\vp_p(a+1)+\vp_p(b+1)$ is odd then $P_n(a,b)$ is not a perfect square.
\end{conjecture}

\begin{conjecture}[Local-obstruction classification]
For odd $n$, $P_n(a,b)$ fails to be a perfect square precisely when there exists a prime $p$ with $p\nmid n$ for which $\vp_p(a+1)+\vp_p(b+1)$ is odd; otherwise solutions obey an archimedean size constraint and are finite in number.
\end{conjecture}

\begin{conjecture}[Many-factor products]
For every odd $n$ and pairwise coprime $a_1<\cdots<a_k$ with $k\ge 2$, $\prod_i(a_i^n+1)$ is a perfect square only if $\sum_i \vp_2(a_i+1)$ is even and the higher-prime parities vanish; in particular, for $k$ odd with all $a_i\equiv 1\pmod 4$ it is never a square.
\end{conjecture}

\section{The Archimedean Regime and Related Context}

When every prime parity is even, squareness must be excluded globally: writing $P_n(a,b)=a^nb^n+a^n+b^n+1$ and comparing with $\lfloor\sqrt{P_n(a,b)}\rfloor^2$, the fractional distance to the nearest square is bounded away from zero over the window of Theorem~\ref{thm:bounded}; making this uniform in $(a,b,n)$ for parity-even cases is the principal remaining analytic task. The mechanism sits within the classical study of perfect powers among values of $a^n\pm 1$ (Lucas--Lehmer sequences, primitive divisors, Catalan-type problems); the novelty is the product of two shifted powers and the exponent-free parity obstruction extracted from the lifting-the-exponent principle.

\section{Discussion and Conclusion}

The through-line is a reversal of expectation: the exponent $n$, which inflates the numbers, is exactly the datum that does not affect the decisive $2$-adic obstruction. This turns an ostensibly $n$-dependent problem into a parity computation on $a+1$ and $b+1$ and opens a prime-by-prime sieve that should account for all non-solutions outside a finite archimedean-controlled set. Theorem~\ref{thm:bounded} anchors the conjecture with unconditional evidence, while Theorems~\ref{thm:collapse} and~\ref{thm:parity} supply the structural reason.

